tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "list_artifacts",
    "description": "Entdecke deine Umwelt: welche verifizierten Artefakttypen mit wie vielen Items dir zur Verf\u00FCgung stehen. Rufe es ZUERST.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "search_items",
    "description": "Suche Items per Stichwort \u00FCber ALLE verf\u00FCgbaren Artefakte (grobe Volltextsuche). N\u00FCtzlich, um relevante Items gezielt zu finden.",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string"
        }
      },
      "required": [
        "query"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_item",
    "description": "Hole EIN einzelnes Item (Text \u002B Artefakttyp) per itemId.",
    "parameters": {
      "type": "object",
      "properties": {
        "itemId": {
          "type": "string"
        }
      },
      "required": [
        "itemId"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_baseline_items",
    "description": "Liefert die GEPR\u00DCFTEN Quell-Items (itemId \u002B Text) EINES Artefakttyps dieser Ableitung. Rufe es f\u00FCr jeden Typ, den du f\u00FCr die Ableitung brauchst. Nur die zugelassenen Quelltypen sind verf\u00FCgbar.",
    "parameters": {
      "type": "object",
      "properties": {
        "artifactType": {
          "type": "string"
        }
      },
      "required": [
        "artifactType"
      ]
    }
  },
  {
    "type": "function",
    "name": "check_anchor",
    "description": "Pr\u00FCft deterministisch, ob eine itemId in den geladenen Quell-Items existiert. Nutze es zur Selbstkontrolle, bevor du ein Item als Anker verwendest.",
    "parameters": {
      "type": "object",
      "properties": {
        "itemId": {
          "type": "string"
        }
      },
      "required": [
        "itemId"
      ]
    }
  },
  {
    "type": "function",
    "name": "save_derived",
    "description": "Schreibt DEINE abgeleiteten Items als offizielles derived.json. Jedes Item braucht text \u002B sourceArtifactItemIds (\u003E=1 echte itemId) \u002B optional assumptions \u002B rationale. Stabile IDs werden automatisch vergeben. Rufe es GENAU EINMAL am Ende auf.",
    "parameters": {
      "type": "object",
      "properties": {
        "items": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "text": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "sourceArtifactItemIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "assumptions": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "rationale": {
                "type": [
                  "string",
                  "null"
                ]
              }
            },
            "required": [
              "text",
              "sourceArtifactItemIds",
              "assumptions",
              "rationale"
            ]
          }
        }
      },
      "required": [
        "items"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_source_claims",
    "description": "Drill-down: liefert die zugrunde liegenden Ledger-Claims (die EVIDENZ unter einem gepr\u00FCften Item) f\u00FCr eine itemId \u2014 die Belege, aus denen das Item extrahiert wurde. Nutze es, wenn ein Item-Text allein f\u00FCr die Ableitung nicht reicht.",
    "parameters": {
      "type": "object",
      "properties": {
        "itemId": {
          "type": "string"
        }
      },
      "required": [
        "itemId"
      ]
    }
  },
  {
    "type": "function",
    "name": "find_related_items",
    "description": "Liefert andere GEPR\u00DCFTE Items (auch aus anderen Artefakttypen), die mit der itemId dieselbe Evidenz teilen (gemeinsame Ledger-Claims) \u2014 f\u00FCr Cross-Artifact-Bez\u00FCge, ohne die Evidenzmenge zu verlassen.",
    "parameters": {
      "type": "object",
      "properties": {
        "itemId": {
          "type": "string"
        }
      },
      "required": [
        "itemId"
      ]
    }
  },
  {
    "type": "function",
    "name": "account_uncovered",
    "description": "Vermerke eine GRUPPE von Quell-Items, die du BEWUSST NICHT ableitest, mit gemeinsamem Grund (dismiss=true). Um eine KOLLISION aufzul\u00F6sen (du willst ein zuvor verworfenes Item doch als Anker nutzen): rufe es mit dismiss=false und den betroffenen ids auf \u2014 das NIMMT die Verwerfung ZUR\u00DCCK. Verwirf NICHTS, was du als Anker nutzt. Keine Mengen-Quote \u2014 nur Rechenschaft.",
    "parameters": {
      "type": "object",
      "properties": {
        "itemIds": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "reason": {
          "type": "string"
        },
        "dismiss": {
          "type": "boolean",
          "default": true
        }
      },
      "required": [
        "itemIds",
        "reason"
      ]
    }
  },
  {
    "type": "function",
    "name": "check_accountability",
    "description": "READ-ONLY Rechenschafts-Feedback zu DEINEM aktuellen Entwurf: \u00FCbergib dieselben Items wie f\u00FCr save_derived; es meldet, welche Quell-Items noch UNBEHANDELT sind und welche du als Anker nutzt UND zugleich verworfen hast (Kollision). Nutze es VOR save_derived, arbeite die offenen Punkte selbst ab und pr\u00FCfe erneut. Mehrfach erlaubt. Der Host korrigiert NICHT \u2014 du.",
    "parameters": {
      "type": "object",
      "properties": {
        "items": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "text": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "sourceArtifactItemIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "assumptions": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "rationale": {
                "type": [
                  "string",
                  "null"
                ]
              }
            },
            "required": [
              "text",
              "sourceArtifactItemIds",
              "assumptions",
              "rationale"
            ]
          }
        }
      },
      "required": [
        "items"
      ]
    }
  },
  {
    "type": "function",
    "name": "verify_derived",
    "description": "Pr\u00FCft DEINEN ENTWURF (noch NICHT gespeichert): je Item, ob die Anker existieren (anchorOk) und ob das Risiko aus seinen Ankern folgt (verdict). Nutze es VOR save_derived, \u00FCberarbeite schwache Items, pr\u00FCfe erneut. Mehrfach erlaubt.",
    "parameters": {
      "type": "object",
      "properties": {
        "items": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "text": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "sourceArtifactItemIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "assumptions": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "rationale": {
